using System;using System.Collections.Generic;using Exoduser.UnityPort.Core.Skills;
namespace Exoduser.UnityPort.Core {public sealed partial class Simulation {
 internal static bool FusionExecutorReady(string key){return key=="shieldFuse"||key=="pillarSpike"||key=="timeStep";}
 bool IsSkillExecutorReady(string id){if(!IsPorted(id))return false;foreach(var key in Skills.Fused){var f=FullSkillLedger.Fusion(key);if(f!=null&&!FusionExecutorReady(key)&&Array.IndexOf(f.Members,id)>=0)return false;}return true;}
 public FullSkillLedger ReadSkillLedger(){var l=new FullSkillLedger{Sp=Player.StatPoints,Malice=Materials,PlayerLevel=Player.Level,Demo=Config.DemoMode,ExecutorReady=IsSkillExecutorReady,FusionReady=FusionExecutorReady,Lmb=preservedLoadedLmbSkill??Config.ActiveAttack,Magic=Skills.MagicSkill,Rmb=Skills.RmbSkill,Charge=Skills.ChargeSkill,Q=Skills.QSkill,Ct=preservedLoadedCtSkill??Skills.CtSkill,Bow=Skills.BowSkill,Tech=Skills.TechSkill,Ultimate=Skills.UltSlot};foreach(var p in loadedDisplaySkillLevels)l.Levels[p.Key]=(int)p.Value;foreach(var p in Skills.Levels)l.Levels[p.Key]=p.Value;l.Levels["kiSlash"]=Math.Max(1,Config.KiSlashLevel);l.Fused.AddRange(Skills.Fused);for(int i=0;i<6;i++)l.Slots[i]=Skills.Slots[i];return l;}
 void ApplySkillLedger(FullSkillLedger l){foreach(var id in PortedSkillIds){if(l.Levels.TryGetValue(id,out int level)&&level>0)Skills.Levels[id]=level;else Skills.Levels.Remove(id);}Config.KiSlashLevel=Math.Max(1,l.Level("kiSlash"));Player.StatPoints=l.Sp;Materials=l.Malice;Skills.Fused.Clear();Skills.Fused.AddRange(l.Fused);for(int i=0;i<6;i++)Skills.Slots[i]=l.Slots[i];if(l.Lmb!=null&&IsPorted(l.Lmb)){Config.ActiveAttack=l.Lmb;preservedLoadedLmbSkill=null;}else preservedLoadedLmbSkill=l.Lmb;Skills.MagicSkill=l.Magic;Skills.RmbSkill=l.Rmb;Skills.ChargeSkill=l.Charge;Skills.QSkill=l.Q;Skills.CtSkill=l.Ct;Skills.BowSkill=l.Bow;Skills.TechSkill=l.Tech;Skills.UltSlot=l.Ultimate;preservedLoadedCtSkill=null;ShieldFuse=l.IsFused("shieldFuse");MaliceSwipeLevel=Skills.Level("maliceSwipe");ShieldThrowLevel=Skills.Level("shieldThrow");}
 bool ChangeSkillLedger(Func<FullSkillLedger,bool> action){var l=ReadSkillLedger();if(!action(l))return false;ApplySkillLedger(l);return true;}
 public int[] RecommendSkills(){var l=ReadSkillLedger();var result=l.Recommend();if(result[0]>0||result[1]>0)ApplySkillLedger(l);return result;}
 public int UpgradeAllSkills(){var l=ReadSkillLedger();int result=l.BatchUpgrade();if(result>0)ApplySkillLedger(l);return result;}
 public bool CanFuseSkill(string key){var l=ReadSkillLedger();var f=FullSkillLedger.Fusion(key);return f!=null&&l.CanFuse(key)&&l.Sp>=f.Star*3;}
 public bool FuseSkill(string key){return ChangeSkillLedger(l=>l.TryFuse(key));}
 public bool CanEquipSkill(int slot,string id){return ReadSkillLedger().CanEquip(slot,id);}
 public bool EquipSkill(int slot,string id){return ChangeSkillLedger(l=>l.Equip(slot,id));}
 public bool UnequipSkill(int slot){return ChangeSkillLedger(l=>l.Unequip(slot));}
 public int SkillLearnMalice(string id){return FullSkillLedger.Definition(id)?.LearnMalice??0;}
 public bool CanLearnSkill(string id){return ReadSkillLedger().CanLearn(id);}
 public bool LearnSkill(string id){return ChangeSkillLedger(l=>l.Learn(id));}
 public bool CanLowerSkillLevel(string id){return ReadSkillLedger().Lower(id);}
 public bool LowerSkillLevel(string id){return ChangeSkillLedger(l=>l.Lower(id));}
 public int SkillResetRefund(string id){return ReadSkillLedger().ResetRefund(id);}
 public bool CanResetSkill(string id){return ReadSkillLedger().Reset(id,true);}
 public bool ResetSkill(string id,bool confirmed){return ChangeSkillLedger(l=>l.Reset(id,confirmed));}
 void RepairRestoredSkillSlots(bool[] reserved){var l=ReadSkillLedger();var absorbed=l.Absorbed();var fixedKick=new HashSet<string>{"bladeShot","fanShot","omniBeam","bladeDash","ghostWalk","iceOrb","timeWarp"};var autoExcluded=new HashSet<string>{"bladeShot","fanShot","omniBeam","bladeDash","shieldThrow","blastShot","ghostWalk","iceOrb","timeWarp","chainSlam","chainAssault","chainSlash","needleShot","peaceShield","hellRay","blueShot","burstLoop","holyDome","fireball","arcLaser","ltnChaser"};Func<int,bool> empty=i=>Skills.Slots[i]==null&&!reserved[i];for(int i=0;i<6;i++){string id=Skills.Slots[i];if(id!=null&&(!Skills.Learned(id)||absorbed.Contains(id)||fixedKick.Contains(id)))Skills.Slots[i]=null;}var displaced=new List<string>();foreach(int i in new[]{5,4}){string id=Skills.Slots[i];if(id!=null&&!FullSkillLedger.CanAssign(id,i)){displaced.Add(id);Skills.Slots[i]=null;}}for(int i=0;i<4;i++){string id=Skills.Slots[i];if(id==null||FullSkillLedger.CanAssign(id,i))continue;Skills.Slots[i]=null;if(FullSkillLedger.CanAssign(id,5)&&empty(5))Skills.Slots[5]=id;else if(FullSkillLedger.CanAssign(id,4)&&empty(4))Skills.Slots[4]=id;}foreach(string id in displaced){if(Array.IndexOf(Skills.Slots,id)>=0)continue;if(FullSkillLedger.CanAssign(id,5)&&empty(5)){Skills.Slots[5]=id;continue;}if(FullSkillLedger.CanAssign(id,4)&&empty(4)){Skills.Slots[4]=id;continue;}for(int i=0;i<4;i++)if(empty(i)&&FullSkillLedger.CanAssign(id,i)){Skills.Slots[i]=id;break;}}foreach(var d in FullSkillLedger.Definitions){if(!d.Active||d.Ultimate||!IsPorted(d.Id)||!Skills.Learned(d.Id)||absorbed.Contains(d.Id)||autoExcluded.Contains(d.Id)||Array.IndexOf(Skills.Slots,d.Id)>=0)continue;for(int i=0;i<6;i++)if(empty(i)&&FullSkillLedger.CanAssign(d.Id,i)){Skills.Slots[i]=d.Id;break;}}}
 public void ApplyLoadedStarterSkillDefaults(Dictionary<string,double> savedSkills,bool forceCtrl=false){Skills.Levels["iceOrb"]=Math.Max(1,Skills.Level("iceOrb"));double level;bool learned=Skills.CtSkill!=null&&savedSkills!=null&&savedSkills.TryGetValue(Skills.CtSkill,out level)&&level>=1;if(forceCtrl||!Skills.Learned(Skills.CtSkill)&&!learned)Skills.CtSkill="iceOrb";}
}}
